from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]

REPLACEMENTS = {
    "OpenRouterClient": "AiClient",
    "OpenRouterOptions": "AiClientOptions",
    "AURA_OPENROUTER_KEY": "AURA_API_KEY",
    "AURA.AI.Providers": "AURA.AI.UniversalAI",
    "OpenRouter": "AI provider",
}

for path in ROOT.rglob("*"):
    if not path.is_file() or ".git" in path.parts:
        continue
    if path.suffix.lower() not in {".cs", ".csproj", ".json", ".xaml", ".md", ".yml", ".yaml"}:
        continue
    try:
        text = path.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        continue
    original = text
    for old, new in REPLACEMENTS.items():
        text = text.replace(old, new)
    if text != original:
        path.write_text(text, encoding="utf-8")

for path in [ROOT / "config/providers.json", ROOT / "src/AURA.AI/UniversalAI/UniversalProviderRegistry.cs"]:
    if path.exists():
        path.unlink()

(ROOT / "src/AURA.AI/UniversalAI/UniversalProvider.cs").write_text('''namespace AURA.AI.UniversalAI;\n\npublic enum UniversalApiFormat\n{\n    OpenAiCompatible,\n    AnthropicMessages,\n    GeminiGenerateContent\n}\n\npublic enum UniversalApiKeyLocation\n{\n    Header,\n    Query,\n    None\n}\n\npublic sealed record UniversalProvider(\n    string Id,\n    string Name,\n    string BaseUrl,\n    string ModelsUrl,\n    UniversalApiFormat Format = UniversalApiFormat.OpenAiCompatible,\n    string AuthHeader = "Authorization",\n    string AuthScheme = "Bearer",\n    bool RequiresApiKey = true,\n    UniversalApiKeyLocation ApiKeyLocation = UniversalApiKeyLocation.Header,\n    string ApiKeyQueryParameter = "key",\n    string HeadersJson = "{}");\n\npublic sealed record UniversalModel(string Id, string DisplayName, string ProviderId, string? OwnedBy = null);\n\npublic sealed record UniversalConnection(UniversalProvider Provider, string ApiKey, string Model);\n''', encoding="utf-8")

(ROOT / "src/AURA.AI/UniversalAI/UniversalRuntimeAdapter.cs").write_text('''namespace AURA.AI.UniversalAI;\n\npublic static class UniversalRuntimeAdapter\n{\n    public static UniversalConnection CreateConnection(string providerId, string providerName, string apiKey, string model, string baseUrl, string modelsUrl, UniversalApiFormat format, string authHeader, string authScheme, UniversalApiKeyLocation keyLocation, string keyQueryParameter, string headersJson)\n    {\n        if (string.IsNullOrWhiteSpace(providerId)) throw new ArgumentException("Identificador do provedor obrigatório.", nameof(providerId));\n        if (string.IsNullOrWhiteSpace(providerName)) providerName = providerId;\n        if (string.IsNullOrWhiteSpace(model)) throw new ArgumentException("Modelo obrigatório.", nameof(model));\n        if (string.IsNullOrWhiteSpace(baseUrl)) throw new ArgumentException("Endpoint obrigatório.", nameof(baseUrl));\n        if (string.IsNullOrWhiteSpace(modelsUrl)) throw new ArgumentException("Endpoint de modelos obrigatório.", nameof(modelsUrl));\n        var provider = new UniversalProvider(providerId.Trim(), providerName.Trim(), baseUrl.Trim(), modelsUrl.Trim(), format, string.IsNullOrWhiteSpace(authHeader) ? "Authorization" : authHeader.Trim(), authScheme?.Trim() ?? string.Empty, keyLocation != UniversalApiKeyLocation.None, keyLocation, string.IsNullOrWhiteSpace(keyQueryParameter) ? "key" : keyQueryParameter.Trim(), string.IsNullOrWhiteSpace(headersJson) ? "{}" : headersJson.Trim());\n        return new UniversalConnection(provider, apiKey?.Trim() ?? string.Empty, model.Trim());\n    }\n}\n''', encoding="utf-8")

(ROOT / "src/AURA.AI/UniversalAI/UniversalAiClientFactory.cs").write_text('''namespace AURA.AI.UniversalAI;\n\npublic static class UniversalAiClientFactory\n{\n    public static AiClient Create(UniversalConnection connection, int maxTokens = 1500, int timeoutSeconds = 90)\n    {\n        if (connection is null) throw new ArgumentNullException(nameof(connection));\n        var provider = connection.Provider ?? throw new ArgumentException("Configuração do provedor obrigatória.", nameof(connection));\n        if (provider.RequiresApiKey && string.IsNullOrWhiteSpace(connection.ApiKey)) throw new ArgumentException("API key obrigatória para o provedor configurado.", nameof(connection));\n        if (string.IsNullOrWhiteSpace(connection.Model)) throw new ArgumentException("Modelo obrigatório.", nameof(connection));\n        if (string.IsNullOrWhiteSpace(provider.BaseUrl)) throw new ArgumentException("Endpoint obrigatório.", nameof(connection));\n        return new AiClient(new AiClientOptions { Provider = provider.Id, ApiKey = connection.ApiKey, BaseUrl = provider.BaseUrl, ModelsUrl = provider.ModelsUrl, Model = connection.Model, MaxTokens = maxTokens, TimeoutSeconds = timeoutSeconds, ApiFormat = provider.Format, AuthHeaderName = provider.AuthHeader, AuthScheme = provider.AuthScheme, ApiKeyLocation = provider.ApiKeyLocation, ApiKeyQueryParameter = provider.ApiKeyQueryParameter, HeadersJson = provider.HeadersJson });\n    }\n}\n''', encoding="utf-8")

(ROOT / "src/AURA.AI/UniversalAI/UniversalModelDiscovery.cs").write_text('''using System.Text.Json;\n\nnamespace AURA.AI.UniversalAI;\n\npublic sealed class UniversalModelDiscovery\n{\n    private readonly HttpClient _http;\n    public UniversalModelDiscovery(HttpClient http) => _http = http ?? throw new ArgumentNullException(nameof(http));\n    public async Task<IReadOnlyList<UniversalModel>> LoadAsync(UniversalProvider provider, string apiKey, CancellationToken ct = default)\n    {\n        if (provider is null) throw new ArgumentNullException(nameof(provider));\n        using var request = new HttpRequestMessage(HttpMethod.Get, AddApiKey(provider.ModelsUrl, provider, apiKey));\n        ApplyHeaders(request, provider, apiKey);\n        using var response = await _http.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, ct).ConfigureAwait(false);\n        string body = await response.Content.ReadAsStringAsync(ct).ConfigureAwait(false);\n        if (!response.IsSuccessStatusCode) throw new HttpRequestException($"Falha ao carregar modelos: {(int)response.StatusCode} {response.ReasonPhrase}. {body[..Math.Min(body.Length, 500)]}");\n        return Parse(provider.Id, body);\n    }\n    private static string AddApiKey(string url, UniversalProvider provider, string key)\n    {\n        if (provider.ApiKeyLocation != UniversalApiKeyLocation.Query || string.IsNullOrWhiteSpace(key)) return url;\n        return url + (url.Contains('?') ? "&" : "?") + Uri.EscapeDataString(provider.ApiKeyQueryParameter) + "=" + Uri.EscapeDataString(key);\n    }\n    private static void ApplyHeaders(HttpRequestMessage request, UniversalProvider provider, string key)\n    {\n        if (provider.ApiKeyLocation == UniversalApiKeyLocation.Header && !string.IsNullOrWhiteSpace(key)) request.Headers.TryAddWithoutValidation(provider.AuthHeader, string.IsNullOrWhiteSpace(provider.AuthScheme) ? key : provider.AuthScheme + " " + key);\n        try { using var doc = JsonDocument.Parse(provider.HeadersJson ?? "{}"); if (doc.RootElement.ValueKind == JsonValueKind.Object) foreach (var p in doc.RootElement.EnumerateObject()) if (p.Value.ValueKind == JsonValueKind.String) request.Headers.TryAddWithoutValidation(p.Name, p.Value.GetString()); } catch (JsonException) { }\n    }\n    private static IReadOnlyList<UniversalModel> Parse(string providerId, string json)\n    {\n        using var doc = JsonDocument.Parse(json); var root = doc.RootElement; var result = new List<UniversalModel>(); var collection = root;\n        if (root.ValueKind == JsonValueKind.Object) { if (root.TryGetProperty("data", out var data)) collection = data; else if (root.TryGetProperty("models", out var models)) collection = models; }\n        if (collection.ValueKind != JsonValueKind.Array) return result;\n        foreach (var item in collection.EnumerateArray()) { string? id = null; string? owned = null; if (item.ValueKind == JsonValueKind.String) id = item.GetString(); else if (item.ValueKind == JsonValueKind.Object) { if (item.TryGetProperty("id", out var idNode)) id = idNode.GetString(); if (string.IsNullOrWhiteSpace(id) && item.TryGetProperty("name", out var nameNode)) id = nameNode.GetString(); if (item.TryGetProperty("owned_by", out var ownerNode)) owned = ownerNode.GetString(); } if (!string.IsNullOrWhiteSpace(id)) result.Add(new UniversalModel(id!, id!, providerId, owned)); }\n        return result.OrderBy(x => x.DisplayName, StringComparer.OrdinalIgnoreCase).ToArray();\n    }\n}\n''', encoding="utf-8")

(ROOT / "src/AURA.AI/AiClient.cs").write_text('''using System.Net;\nusing System.Text;\nusing System.Text.Json;\nusing AURA.Core.Logging;\nusing AURA.AI.UniversalAI;\n\nnamespace AURA.AI;\n\npublic sealed class AiClientOptions\n{\n    public string Provider { get; set; } = string.Empty;\n    public string ApiKey { get; set; } = string.Empty;\n    public string BaseUrl { get; set; } = string.Empty;\n    public string ModelsUrl { get; set; } = string.Empty;\n    public string Model { get; set; } = string.Empty;\n    public int MaxTokens { get; set; } = 1500;\n    public int TimeoutSeconds { get; set; } = 90;\n    public UniversalApiFormat ApiFormat { get; set; } = UniversalApiFormat.OpenAiCompatible;\n    public string AuthHeaderName { get; set; } = "Authorization";\n    public string AuthScheme { get; set; } = "Bearer";\n    public UniversalApiKeyLocation ApiKeyLocation { get; set; } = UniversalApiKeyLocation.Header;\n    public string ApiKeyQueryParameter { get; set; } = "key";\n    public string HeadersJson { get; set; } = "{}";\n    public string AppReference { get; set; } = "AURA";\n}\n\npublic sealed class AiClient\n{\n    public AiClientOptions Options { get; }\n    private readonly ILogger _logger;\n    public AiClient(AiClientOptions options, ILogger? logger = null) { Options = options ?? throw new ArgumentNullException(nameof(options)); _logger = logger ?? new ConsoleLogger(); }\n    public Task<string> ChatAsync(string question, HttpClient? httpClient = null, CancellationToken ct = default) => ChatAsync(question, null, httpClient, ct);\n    public async Task<string> ChatAsync(string question, string? systemPrompt = null, HttpClient? httpClient = null, CancellationToken ct = default)\n    {\n        if (string.IsNullOrWhiteSpace(question)) throw new ArgumentException("A pergunta não pode ser vazia.", nameof(question));\n        var messages = new List<AgentMessage>(); if (!string.IsNullOrWhiteSpace(systemPrompt)) messages.Add(new AgentMessage { Role = "system", Content = systemPrompt }); messages.Add(new AgentMessage { Role = "user", Content = question });\n        var response = await SendAsync(messages, null, httpClient, ct).ConfigureAwait(false); if (!string.IsNullOrWhiteSpace(response.Error)) throw new AgentLlmException(response.Error, response.ErrorKind); return response.Content ?? string.Empty;\n    }\n    public Task<AgentChatResponse> ChatToolsAsync(IReadOnlyList<AgentMessage> messages, IReadOnlyList<AgentToolDefinition> tools, HttpClient? httpClient = null, CancellationToken ct = default, string? systemPrompt = null)\n    {\n        var all = new List<AgentMessage>(); if (!string.IsNullOrWhiteSpace(systemPrompt)) all.Add(new AgentMessage { Role = "system", Content = systemPrompt }); all.AddRange(messages); return SendAsync(all, tools, httpClient, ct);\n    }\n    private async Task<AgentChatResponse> SendAsync(IReadOnlyList<AgentMessage> messages, IReadOnlyList<AgentToolDefinition>? tools, HttpClient? httpClient, CancellationToken ct)\n    {\n        EnsureConfigured(); using var owned = httpClient is null ? new HttpClient() : null; HttpClient http = httpClient ?? owned!;\n        try { using var request = BuildRequest(messages, tools); using var response = await http.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, ct).ConfigureAwait(false); string body = await response.Content.ReadAsStringAsync(ct).ConfigureAwait(false); if (!response.IsSuccessStatusCode) return new AgentChatResponse { Error = $"Falha na chamada LLM ({(int)response.StatusCode} {response.StatusCode}): {body}", ErrorKind = Classify(response.StatusCode) }; return ParseResponse(body); }\n        catch (OperationCanceledException) when (!ct.IsCancellationRequested) { return new AgentChatResponse { Error = "Tempo limite excedido ao chamar o provedor configurado.", ErrorKind = AgentErrorKind.Timeout }; }\n        catch (HttpRequestException ex) { _logger.Error("LLM network error: " + ex.Message); return new AgentChatResponse { Error = ex.Message, ErrorKind = AgentErrorKind.Network }; }\n    }\n    private HttpRequestMessage BuildRequest(IReadOnlyList<AgentMessage> messages, IReadOnlyList<AgentToolDefinition>? tools)\n    {\n        string url = Options.BaseUrl.Trim().Replace("{model}", Uri.EscapeDataString(Options.Model), StringComparison.Ordinal);\n        if (Options.ApiKeyLocation == UniversalApiKeyLocation.Query && !string.IsNullOrWhiteSpace(Options.ApiKey)) url += (url.Contains('?') ? "&" : "?") + Uri.EscapeDataString(Options.ApiKeyQueryParameter) + "=" + Uri.EscapeDataString(Options.ApiKey);\n        var request = new HttpRequestMessage(HttpMethod.Post, url); if (Options.ApiKeyLocation == UniversalApiKeyLocation.Header && !string.IsNullOrWhiteSpace(Options.ApiKey)) request.Headers.TryAddWithoutValidation(Options.AuthHeaderName, string.IsNullOrWhiteSpace(Options.AuthScheme) ? Options.ApiKey : Options.AuthScheme + " " + Options.ApiKey); ApplyCustomHeaders(request);\n        object payload = Options.ApiFormat switch { UniversalApiFormat.AnthropicMessages => BuildAnthropicPayload(messages), UniversalApiFormat.GeminiGenerateContent => BuildGeminiPayload(messages), _ => BuildOpenAiPayload(messages, tools) };\n        request.Content = new StringContent(JsonSerializer.Serialize(payload), Encoding.UTF8, "application/json"); return request;\n    }\n    private object BuildOpenAiPayload(IReadOnlyList<AgentMessage> messages, IReadOnlyList<AgentToolDefinition>? tools)\n    {\n        var msg = messages.Select(m => { var d = new Dictionary<string, object?> { ["role"] = m.Role, ["content"] = m.Content }; if (m.ToolCallId != null) d["tool_call_id"] = m.ToolCallId; if (m.ToolCalls != null) d["tool_calls"] = m.ToolCalls.Select(c => new { id = c.Id, type = "function", function = new { name = c.Name, arguments = c.ArgumentsJson } }).ToArray(); return d; }).ToArray();\n        var payload = new Dictionary<string, object?> { ["model"] = Options.Model, ["messages"] = msg, ["max_tokens"] = Options.MaxTokens };\n        if (tools is { Count: > 0 }) payload["tools"] = tools.Select(t => new { type = "function", function = new { name = t.Name, description = t.Description, parameters = new { type = "object", properties = t.Parameters.ToDictionary(p => p.Key, p => new { type = p.Value.Type, description = p.Value.Description }), required = t.Required } } }).ToArray(); return payload;\n    }\n    private object BuildAnthropicPayload(IReadOnlyList<AgentMessage> messages) { string? system = messages.FirstOrDefault(m => m.Role == "system")?.Content; var content = messages.Where(m => m.Role != "system").Select(m => new { role = m.Role == "assistant" ? "assistant" : "user", content = m.Content ?? string.Empty }).ToArray(); var p = new Dictionary<string, object?> { ["model"] = Options.Model, ["max_tokens"] = Options.MaxTokens, ["messages"] = content }; if (system != null) p["system"] = system; return p; }\n    private object BuildGeminiPayload(IReadOnlyList<AgentMessage> messages) { var contents = messages.Where(m => m.Role != "system").Select(m => new { role = m.Role == "assistant" ? "model" : "user", parts = new[] { new { text = m.Content ?? string.Empty } } }).ToArray(); var system = messages.FirstOrDefault(m => m.Role == "system")?.Content; var p = new Dictionary<string, object?> { ["contents"] = contents, ["generationConfig"] = new { maxOutputTokens = Options.MaxTokens } }; if (system != null) p["systemInstruction"] = new { parts = new[] { new { text = system } } }; return p; }\n    private AgentChatResponse ParseResponse(string body)\n    {\n        try { using var doc = JsonDocument.Parse(body); var root = doc.RootElement; if (Options.ApiFormat == UniversalApiFormat.AnthropicMessages) { string text = root.TryGetProperty("content", out var c) && c.ValueKind == JsonValueKind.Array ? string.Join("", c.EnumerateArray().Where(x => x.TryGetProperty("text", out _)).Select(x => x.GetProperty("text").GetString())) : string.Empty; return new AgentChatResponse { Content = text }; } if (Options.ApiFormat == UniversalApiFormat.GeminiGenerateContent) { string text = string.Empty; if (root.TryGetProperty("candidates", out var candidates) && candidates.ValueKind == JsonValueKind.Array && candidates.GetArrayLength() > 0) { var parts = candidates[0].GetProperty("content").GetProperty("parts"); text = string.Join("", parts.EnumerateArray().Where(x => x.TryGetProperty("text", out _)).Select(x => x.GetProperty("text").GetString())); } return new AgentChatResponse { Content = text }; } var message = root.GetProperty("choices")[0].GetProperty("message"); var result = new AgentChatResponse { Content = message.TryGetProperty("content", out var content) ? content.GetString() : string.Empty }; if (message.TryGetProperty("tool_calls", out var calls) && calls.ValueKind == JsonValueKind.Array) { result.ToolCalls = new List<AgentToolCall>(); foreach (var call in calls.EnumerateArray()) { var fn = call.GetProperty("function"); result.ToolCalls.Add(new AgentToolCall { Id = call.GetProperty("id").GetString() ?? Guid.NewGuid().ToString("N"), Name = fn.GetProperty("name").GetString() ?? string.Empty, ArgumentsJson = fn.GetProperty("arguments").GetString() ?? "{}" }); } } return result; } catch (Exception ex) { return new AgentChatResponse { Error = "Resposta inválida do provedor: " + ex.Message, ErrorKind = AgentErrorKind.InvalidRequest }; }\n    }\n    private void ApplyCustomHeaders(HttpRequestMessage request) { try { using var doc = JsonDocument.Parse(Options.HeadersJson ?? "{}"); if (doc.RootElement.ValueKind == JsonValueKind.Object) foreach (var p in doc.RootElement.EnumerateObject()) if (p.Value.ValueKind == JsonValueKind.String) request.Headers.TryAddWithoutValidation(p.Name, p.Value.GetString()); } catch (JsonException ex) { _logger.Warning("Cabeçalhos personalizados inválidos: " + ex.Message); } }\n    private void EnsureConfigured() { if (string.IsNullOrWhiteSpace(Options.BaseUrl)) throw new InvalidOperationException("Endpoint do provedor não configurado."); if (string.IsNullOrWhiteSpace(Options.Model)) throw new InvalidOperationException("Modelo não configurado."); if (Options.ApiKeyLocation != UniversalApiKeyLocation.None && string.IsNullOrWhiteSpace(Options.ApiKey)) throw new InvalidOperationException("API key não configurada."); }\n    private static AgentErrorKind Classify(System.Net.HttpStatusCode code) => code switch { HttpStatusCode.BadRequest => AgentErrorKind.InvalidRequest, HttpStatusCode.Unauthorized or HttpStatusCode.Forbidden => AgentErrorKind.InvalidApiKey, (HttpStatusCode)402 => AgentErrorKind.PaymentRequired, HttpStatusCode.TooManyRequests => AgentErrorKind.RateLimited, _ when (int)code >= 500 => AgentErrorKind.ProviderError, _ => AgentErrorKind.Unknown };\n}\n''', encoding="utf-8")

(ROOT / "src/AURA.AI/AgentSession.cs").write_text('''using AURA.Core.Logging;\nusing AURA.Memory;\n\nnamespace AURA.AI;\n\npublic sealed class AgentSession\n{\n    private readonly int _maxRounds; private readonly AiClient _client; private readonly ILogger _logger; private readonly List<AgentTool> _tools; private readonly List<AgentMessage> _messages = new(); private readonly string? _systemPrompt; private readonly MemoryStore? _memory;\n    public AgentSession(AiClient client, IEnumerable<AgentTool> tools, string? systemPrompt = null, ILogger? logger = null, MemoryStore? memory = null, int maxRounds = 12) { _client = client ?? throw new ArgumentNullException(nameof(client)); _tools = (tools ?? Enumerable.Empty<AgentTool>()).ToList(); _systemPrompt = systemPrompt; _logger = logger ?? new ConsoleLogger(); _memory = memory; _maxRounds = Math.Max(1, maxRounds); }\n    public event Action<AgentStep>? Step; public IReadOnlyList<AgentMessage> Messages => _messages;\n    public async Task<string> RunAsync(string userText, HttpClient? httpClient = null, CancellationToken ct = default)\n    {\n        if (string.IsNullOrWhiteSpace(userText)) throw new ArgumentException("A instrução não pode ser vazia.", nameof(userText)); _messages.Add(new AgentMessage { Role = "user", Content = userText }); _memory?.Append(MemoryEntry.Question(userText));\n        for (int round = 0; round < _maxRounds; round++) { var response = await _client.ChatToolsAsync(_messages.ToArray(), _tools.Select(t => t.Definition).ToList(), httpClient, ct, _systemPrompt).ConfigureAwait(false); if (!string.IsNullOrWhiteSpace(response.Error)) throw new AgentLlmException(response.Error, response.ErrorKind); if (response.ToolCalls is not { Count: > 0 }) { string answer = response.Content ?? string.Empty; _memory?.Append(MemoryEntry.Answer(answer)); return answer; } _messages.Add(new AgentMessage { Role = "assistant", Content = response.Content, ToolCalls = response.ToolCalls }); foreach (var call in response.ToolCalls) { ct.ThrowIfCancellationRequested(); var tool = _tools.FirstOrDefault(t => string.Equals(t.Definition.Name, call.Name, StringComparison.OrdinalIgnoreCase)); string result; bool success = true; if (tool == null) { result = "ERRO: ferramenta não encontrada: " + call.Name; success = false; } else { try { result = await tool.ExecuteAsync(call.ArgumentsJson, ct).ConfigureAwait(false); } catch (Exception ex) { result = "ERRO: " + ex.Message; success = false; _logger.Error(ex.ToString()); } } _messages.Add(new AgentMessage { Role = "tool", ToolCallId = call.Id, Content = result }); Step?.Invoke(new AgentStep(call.Name, call.ArgumentsJson, result, success)); } }\n        throw new AgentLlmException("O agente atingiu o limite de rodadas sem produzir uma resposta final.", AgentErrorKind.Unknown);\n    }\n}\n''', encoding="utf-8")

(ROOT / "src/AURA.AI/AiAssistantService.cs").write_text('''using AURA.Core.Logging;\nusing AURA.Memory;\n\nnamespace AURA.AI;\n\npublic static class AiAssistantService\n{\n    public static async Task<string> AskAsync(string question, MemoryStore? memory = null, ILogger? logger = null, AiClientOptions? options = null, HttpClient? http = null) { if (string.IsNullOrWhiteSpace(question)) throw new ArgumentException("A pergunta não pode ser vazia.", nameof(question)); var client = new AiClient(options ?? throw new InvalidOperationException("A configuração do provedor não foi fornecida."), logger); memory?.Append(MemoryEntry.Question(question)); string answer = await client.ChatAsync(question, http).ConfigureAwait(false); memory?.Append(MemoryEntry.Answer(answer)); return answer; }\n}\n''', encoding="utf-8")

(ROOT / "src/AURA.AI/AiAssistant.cs").write_text('''using AURA.Core.Logging;\nusing AURA.Memory;\n\nnamespace AURA.AI;\n\npublic sealed class AiAssistant\n{\n    private readonly AiClient _client; private readonly MemoryStore _memory; private readonly ILogger _logger;\n    public AiAssistant(AiClient client, MemoryStore memory, ILogger? logger = null) { _client = client ?? throw new ArgumentNullException(nameof(client)); _memory = memory ?? throw new ArgumentNullException(nameof(memory)); _logger = logger ?? new ConsoleLogger(); }\n    public async Task<string> AskAsync(string question, HttpClient? httpClient = null, CancellationToken ct = default) { _memory.Append(MemoryEntry.Question(question)); string answer = await _client.ChatAsync(question, httpClient, ct).ConfigureAwait(false); _memory.Append(MemoryEntry.Answer(answer)); _logger.Info("IA: pergunta registrada e respondida."); return answer; }\n}\n''', encoding="utf-8")

# Remove the old embedded provider catalog from the AI project.
