(ROOT / "src/AURA.Mobile/Diagnostics/RuntimeConfig.cs").write_text('''using AURA.AI;\nusing AURA.AI.UniversalAI;\n\nnamespace AURA.Mobile.Diagnostics;\n\npublic static class RuntimeConfig\n{\n    private const string KeyPrefix = "ai_key_";\n    public static int MaxTokens { get => Preferences.Default.Get("ai_max_tokens", 1500); set => Preferences.Default.Set("ai_max_tokens", value); }\n    public static int TimeoutSeconds { get => Preferences.Default.Get("ai_timeout_seconds", 90); set => Preferences.Default.Set("ai_timeout_seconds", value); }\n    public static int LogLinesForAnalysis { get => Preferences.Default.Get("ai_log_lines", 120); set => Preferences.Default.Set("ai_log_lines", value); }\n    public static string Provider { get => Preferences.Default.Get("ai_provider", string.Empty); set => Preferences.Default.Set("ai_provider", value?.Trim() ?? string.Empty); }\n    public static string ProviderName { get => Preferences.Default.Get("ai_provider_name", string.Empty); set => Preferences.Default.Set("ai_provider_name", value?.Trim() ?? string.Empty); }\n    public static string Model { get => Preferences.Default.Get("ai_model", string.Empty); set => Preferences.Default.Set("ai_model", value?.Trim() ?? string.Empty); }\n    public static string BaseUrl { get => Preferences.Default.Get("ai_base_url", string.Empty); set => Preferences.Default.Set("ai_base_url", value?.Trim() ?? string.Empty); }\n    public static string ModelsUrl { get => Preferences.Default.Get("ai_models_url", string.Empty); set => Preferences.Default.Set("ai_models_url", value?.Trim() ?? string.Empty); }\n    public static UniversalApiFormat ApiFormat { get => Enum.TryParse<UniversalApiFormat>(Preferences.Default.Get("ai_api_format", "OpenAiCompatible"), true, out var v) ? v : UniversalApiFormat.OpenAiCompatible; set => Preferences.Default.Set("ai_api_format", value.ToString()); }\n    public static UniversalApiKeyLocation ApiKeyLocation { get => Enum.TryParse<UniversalApiKeyLocation>(Preferences.Default.Get("ai_key_location", "Header"), true, out var v) ? v : UniversalApiKeyLocation.Header; set => Preferences.Default.Set("ai_key_location", value.ToString()); }\n    public static string AuthHeader { get => Preferences.Default.Get("ai_auth_header", "Authorization"); set => Preferences.Default.Set("ai_auth_header", value?.Trim() ?? ""); }\n    public static string AuthScheme { get => Preferences.Default.Get("ai_auth_scheme", "Bearer"); set => Preferences.Default.Set("ai_auth_scheme", value?.Trim() ?? ""); }\n    public static string KeyQueryParameter { get => Preferences.Default.Get("ai_key_query", "key"); set => Preferences.Default.Set("ai_key_query", value?.Trim() ?? "key"); }\n    public static string HeadersJson { get => Preferences.Default.Get("ai_headers_json", "{}"); set => Preferences.Default.Set("ai_headers_json", value ?? "{}"); }\n    public static string LastStatusMessage { get; private set; } = string.Empty;\n    public static string ApiKey { get => GetApiKeyForProvider(Provider); set => SetApiKeyForProvider(Provider, value); }\n    public static string GetApiKeyForProvider(string? providerId) { string id = Normalize(providerId); if (id.Length == 0) return string.Empty; try { return SecureStorage.Default.GetAsync(KeyPrefix + id).GetAwaiter().GetResult()?.Trim() ?? string.Empty; } catch { return string.Empty; } }\n    public static void SetApiKeyForProvider(string? providerId, string? value) { string id = Normalize(providerId); if (id.Length == 0) return; try { if (string.IsNullOrWhiteSpace(value)) SecureStorage.Default.Remove(KeyPrefix + id); else SecureStorage.Default.SetAsync(KeyPrefix + id, value.Trim()).GetAwaiter().GetResult(); } catch { } }\n    private static string Normalize(string? value) => new string((value ?? string.Empty).Trim().ToLowerInvariant().Select(c => char.IsLetterOrDigit(c) || c is '-' or '_' ? c : '_').ToArray());\n    public static UniversalConnection BuildConnection() => UniversalRuntimeAdapter.CreateConnection(Provider, ProviderName, ApiKey, Model, BaseUrl, ModelsUrl, ApiFormat, AuthHeader, AuthScheme, ApiKeyLocation, KeyQueryParameter, HeadersJson);\n    public static void Apply(AiClient client) { if (client == null) throw new ArgumentNullException(nameof(client)); var connection = BuildConnection(); var configured = UniversalAiClientFactory.Create(connection, MaxTokens, TimeoutSeconds); client.Options.Provider = configured.Options.Provider; client.Options.ApiKey = configured.Options.ApiKey; client.Options.BaseUrl = configured.Options.BaseUrl; client.Options.ModelsUrl = configured.Options.ModelsUrl; client.Options.Model = configured.Options.Model; client.Options.MaxTokens = configured.Options.MaxTokens; client.Options.TimeoutSeconds = configured.Options.TimeoutSeconds; client.Options.ApiFormat = configured.Options.ApiFormat; client.Options.AuthHeaderName = configured.Options.AuthHeaderName; client.Options.AuthScheme = configured.Options.AuthScheme; client.Options.ApiKeyLocation = configured.Options.ApiKeyLocation; client.Options.ApiKeyQueryParameter = configured.Options.ApiKeyQueryParameter; client.Options.HeadersJson = configured.Options.HeadersJson; LastStatusMessage = ProviderName + " · " + Model + " · " + BaseUrl; }\n    public static void ApplyUniversal(AiClient client, string providerId, string providerName, string apiKey, string model, string baseUrl, string modelsUrl, UniversalApiFormat format, UniversalApiKeyLocation keyLocation, string authHeader, string authScheme, string keyQuery, string headersJson) { Provider = providerId; ProviderName = providerName; Model = model; BaseUrl = baseUrl; ModelsUrl = modelsUrl; ApiFormat = format; ApiKeyLocation = keyLocation; AuthHeader = authHeader; AuthScheme = authScheme; KeyQueryParameter = keyQuery; HeadersJson = headersJson; SetApiKeyForProvider(providerId, apiKey); Apply(client); }\n    public static string? EnsureReadyForRequest(AiClient client) { if (client == null) return "Cliente de IA indisponível."; if (string.IsNullOrWhiteSpace(Provider)) return "Configure o identificador do provedor."; if (string.IsNullOrWhiteSpace(BaseUrl)) return "Configure o endpoint do provedor."; if (string.IsNullOrWhiteSpace(ModelsUrl)) return "Configure o endpoint de modelos."; if (string.IsNullOrWhiteSpace(Model)) return "Selecione um modelo."; if (ApiKeyLocation != UniversalApiKeyLocation.None && string.IsNullOrWhiteSpace(ApiKey)) return "Configure a chave de API."; return null; }\n}\n''', encoding="utf-8")

